    $('#draw').onclick=()=>drawCards();$('#draw-pile').onclick=()=>drawCards();$('#library-open').onclick=()=>openZoneViewer('library');$('#graveyard-open').onclick=()=>openZoneViewer('graveyard','all');$('#exile-open').onclick=()=>openZoneViewer('exile','all');$('#library-view-top').onclick=()=>{libraryView='top';renderZoneViewer();};$('#library-view-all').onclick=()=>{libraryView='all';renderZoneViewer();};$('#zone-view-close').onclick=()=>$('#zone-view-dialog').close();$('#shuffle').onclick=()=>{state.library=shuffleArray(state.library);save();render();logAction('a mélangé sa bibliothèque');};
