    const untap=()=>{state.battlefield.forEach(c=>c.tapped=false);save();render();logAction('a dégagé toutes ses cartes');};$('#untap-all').onclick=untap;$('#untap-all-footer').onclick=untap;$('#token-btn').onclick=createToken;$('#counter-btn').onclick=newDie;$('#roll').onclick=randomDie;$('#flip').onclick=()=>{const result=Math.random()<.5?'Pile':'Face';logAction(`a lancé une pièce : ${result}`);toast(result);};
    $('#pass-turn').onclick=passPriority;$('#ready-btn').onclick=toggleReady;$('#combat-btn').onclick=finishCombatStep;$('#leave-room').onclick=leaveRoom;$('#draw-pile').title='Draw a card';$('#player-name').onchange=e=>updatePlayerName(e.target.value);$('#player-name-setting').onchange=e=>updatePlayerName(e.target.value);
