    $('#command-open').onclick=openSearchDeck;$('#commands-menu-open').onclick=()=>{$('#command-dialog').showModal();$('#command-search').focus();};$('#close-command').onclick=()=>$('#command-dialog').close();$$('.command-list button').forEach(b=>b.onclick=()=>command(b.dataset.command));$('#command-search').oninput=e=>$$('.command-list button').forEach(b=>b.classList.toggle('hidden',!b.textContent.toLowerCase().includes(e.target.value.toLowerCase())));
    $('#search-deck-close').onclick=()=>$('#search-deck-dialog').close();$('#search-deck-input').oninput=renderSearchDeck;$('#search-deck-order').onchange=e=>{searchDeckOrder=e.target.value;renderSearchDeck();};$$('#search-deck-dialog [data-reveal]').forEach(b=>b.onclick=()=>{searchReveal=b.dataset.reveal;$$('#search-deck-dialog [data-reveal]').forEach(x=>x.classList.toggle('active',x===b));renderSearchDeck();});$('#search-deck-shuffle').onclick=()=>{state.library=shuffleArray(state.library);save();render();logAction('a mélangé sa bibliothèque');$('#search-deck-dialog').close();};$('#search-deck-dialog').addEventListener('click',e=>{if(e.target===$('#search-deck-dialog'))$('#search-deck-dialog').close();});document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();if(!$('#search-deck-dialog').open)openSearchDeck();else $('#search-deck-input').focus();return;}if(!$('#search-deck-dialog').open||e.altKey||e.ctrlKey||e.metaKey)return;const target=e.target;if(target instanceof HTMLInputElement||target instanceof HTMLTextAreaElement||target instanceof HTMLSelectElement)return;const zones={h:'hand',d:'graveyard',s:'exile',t:'top',y:'bottom'};const destination=zones[e.key.toLowerCase()];if(destination){e.preventDefault();moveSearchedCard(destination);}});
